  'exif-remover': { title: 'EXIF Remover – Remove Photo Metadata & GPS', desc: 'Free EXIF remover: view and remove photo metadata like camera model, date and GPS location. JPEG and PNG metadata is removed without re-compressing.', h1: 'EXIF Viewer and Remover', intro: 'This EXIF remover shows the hidden data in your photos, including GPS location, and downloads a clean copy. Phone photos often contain the exact place they were taken.', example: ex('A JPEG from a phone with location turned on shows its latitude and longitude here. The clean copy keeps the image data byte for byte and drops only the metadata blocks.') },
