  'spacing-scale-generator': { title: 'Spacing Scale Generator – 4pt & 8pt Grid Tokens', desc: 'Free spacing scale generator. Build a consistent 4pt or 8pt grid spacing scale for your design system and export CSS variables or JSON tokens.', intro: 'This spacing scale generator builds consistent spacing tokens from a base unit and a progression, ready for CSS or a design token file.', example: ex('A 4px base with the practical progression gives 2, 4, 6, 8, 12, 16, 20, 24, 32 and 40px: fine steps for padding inside components and larger ones for spacing between sections.') },
